                Rectangle {
                    Layout.preferredHeight: 14
                    radius: 7
                    color: poseBridge.dirty ? "#e5b567" : "#3a4a3d"
                    Label {
                        anchors.centerIn: parent
                        text: poseBridge.dirty ? qsTr("● unsaved")
                                               : qsTr("saved")
                        color: poseBridge.dirty ? "#2a2118" : "#8fbf96"
                        font.pixelSize: 10
                    }
                }
            }

